import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M7 8a1 1 0 0 0 0-2H4a1 1 0 0 0-1 1v3a1 1 0 0 0 2 0v-.637l2.36 2.358a.962.962 0 0 0 1.36-1.358L6.355 8zM1 1c-.6 0-1 .5-1 1v12a1 1 0 0 0 1 1h14c.6 0 1-.4 1-1V2a1 1 0 0 0-1-1zm13 12H2V5h12z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M3 8a1 1 0 0 1 1-1h5a1 1 0 0 1 0 2H6.414l5.293 5.293a1 1 0 1 1-1.414 1.414L5 10.414V13a1 1 0 0 1-2 0zm17 10a1 1 0 0 1-1 1H1a1 1 0 0 1-1-1V2c0-.5.4-1 1-1h18a1 1 0 0 1 1 1zm-2-1V6H2v11z"] as readonly string[];

export const ThVirtualIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="th-virtual" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
ThVirtualIcon.displayName = `Blueprint6.Icon.ThVirtualIcon`;

/**
 * @deprecated Use {@link ThVirtualIcon} instead.
 */
export const ThVirtual: typeof ThVirtualIcon = ThVirtualIcon;

export default ThVirtualIcon;
